//! Compare source startup/grid candidates with eight retained guarded rows.
use spore_core::{cell_start_grid_v1::project,cell_start_bounds_v1,native_sse::Policy};
fn w(b:&[u8],o:usize)->u32{u32::from_le_bytes(b[o..o+4].try_into().unwrap())}
fn main(){let b=std::fs::read(std::env::args().nth(1).expect("native rows")).unwrap();assert_eq!(b.len(),2880);for i in 0..8{let mode=i/2;let kind=(i%2) as u32;let value=if mode%2==0{0}else{15f32.to_bits()};let rows=project(value,kind,Policy::Mxcsr1f80,true).unwrap();let o=i*336;assert_eq!((w(&b,o),w(&b,o+4),w(&b,o+8),w(&b,o+12)),(rows.len() as u32,kind,mode as u32,0));for (j,row) in rows.iter().enumerate(){for(k,x)in row.iter().enumerate(){assert_eq!(w(&b,o+16+j*20+k*4),*x)}}assert!((o+16+rows.len()*20..o+336).all(|p|b[p]==0));}for i in 0..4{let o=2688+i*48;let v=if i%2==0{0}else{15f32.to_bits()};for(j,x)in cell_start_bounds_v1::project(v,Policy::Mxcsr1f80,true).unwrap().iter().enumerate(){assert_eq!(w(&b,o+j*4),*x)}let fp=w(&b,o+40);assert_eq!(fp&0xffff,if i<2{0x27f}else{0x37f});assert_eq!((fp>>16)&0x3840,0);assert_eq!(w(&b,o+44)&!0x3f,0x1f80);}println!("matched eight guarded startup-grid candidate rows and four bounds rows; synthetic state");}
